Ext.define('GridHTML.view.GridList', {
    extend: 'Ext.Base',

    marginTopBottom: 1,
    marginLeftRight: 2,
    paddingTopBottom: 1,
    paddingLeftRight: 3,

    buildGrid: function(spec, store, opts) {


        var me = this,
            _temp;

        me.Store = store;
        me.GridSpec = spec;
        me.CSSUtils = new GridHTML.view.CSSUtils(spec, store, null);
        me.buildMarginTopBottom = me.marginTopBottom + ' ' + me.marginLeftRight + ' ' + me.marginTopBottom + ' ' + me.marginLeftRight;
        me.buildPadding = me.paddingTopBottom + ' ' + me.paddingLeftRight + ' ' + me.paddingTopBottom + ' ' + me.paddingLeftRight;
        me.buildMarginTopBottomDefault = '0 ' + me.marginLeftRight + ' 0 ' + me.marginTopBottom;

        _temp = Ext.create("Ext.container.Container", {
            layout: {
                type: 'auto'
            },
            scrollable: true,
            style: 'height:100%;',
            width: opts.widthViewport
        });

        window.addEventListener('resize', function() {
            var me = this,
                buildGrid = me.me,
                store = me.store,
                spec = me.spec,
                container = me.container,
                upWidth ;

            if (container === undefined) return;


            upWidth = container.up().getWidth();
            container.removeAll();
            container.setWidth(upWidth);

            buildGrid.getGraphic(spec, store, {
                Container: container
            });

        }.bind({
            container: _temp,
            spec: spec,
            store: store,
            me: me
        }));



        me.getGraphic(spec, store, {
            Container: _temp
        });

        return _temp;


    },

    getGraphic: function(spec, store, opts) {



        var me = this,
            toAdd = opts.Container,
            gridSpec = spec.laf.viewSpec.gridSpec,
            listAttributes = gridSpec.listAttributes,
            itemsContainer,
            cantItems,
            maxWidth,
            itemS,
            amountPerRow = 0,
            containerLenght = toAdd.width,
            colLength,
            rowLength,
            width,
            height;

        colLength = listAttributes.autoColumn == 'true' ? 'auto' : parseInt(listAttributes.columnsCount);
        rowLength = listAttributes.autoRow == 'true' ? 'auto' : parseInt(listAttributes.rowCount);
        width = listAttributes.autoWidth == 'true' ? 'auto' : parseInt(listAttributes.width);
        height = listAttributes.autoHeight == 'true' ? 'auto' : parseInt(listAttributes.height);

        itemsContainer = me.generateItems(width, height, listAttributes, containerLenght);

        cantItems = itemsContainer[1].length;
        maxWidth = itemsContainer[0] + me.marginLeftRight * 2 + me.paddingLeftRight * 2 + 6;
        itemS = itemsContainer[1];

        if (colLength === 'auto' && rowLength === 'auto') {

            if (width !== 'auto') {
                amountPerRow = containerLenght / Math.min(containerLenght, width + 4 * (me.marginLeftRight + me.paddingLeftRight));
            } else {
                amountPerRow = containerLenght / maxWidth;
            }

            amountPerRow = Math.floor(amountPerRow);
            buildStructByColumn(toAdd, amountPerRow, itemS);

        } else if (colLength === 'auto' && rowLength !== 'auto') {
            buildStructByRow(toAdd, rowLength, itemS);
        } else if (colLength !== 'auto') {

            amountPerRow = colLength;
            buildStructByColumn(toAdd, colLength, itemS);
        }

        //****************

        function buildStructByColumn(panel, cantidadColumnas, items) {
            var margin = me.buildMarginTopBottom;

            panel.add({
                xtype: 'container',
                layout: {
                    type: 'table',
                    columns: cantidadColumnas
                },
                defaults: {
                    margin: margin
                },
                items: items
            });
        }

        function buildStructByRow(panel, cantidadFilas, items) {
            var margin = me.buildMarginTopBottom;

            panel.add({
                xtype: 'container',
                layout: {
                    type: 'table',
                    columns: Math.ceil(items.length / cantidadFilas)
                },
                defaults: {
                    margin: margin
                },
                items: items
            });
        }



    },

    generateItems: function(widthItem, heightItem, listAttributes, containerLength) {
        var me = this,
            i,
            j = 0,
            items = [],
            maxValue,
            tempItem,
            data,
            store = me.Store,
            gridGeneral = me.GridSpec.laf.viewSpec.gridSpec.gridGeneral,
            storeCount = store.count(),
            headerFont = gridGeneral.axis.fontSize + 'px ' + gridGeneral.axis.fontType,
            cellsFont = gridGeneral.cells.fontSize + 'px ' + gridGeneral.cells.fontType,

            // FORMAT
            templates = [],
            toDisplay,
            displayTitle,
            columns = -1,
            displayValue,
            displaySource,
            display = gridGeneral.display.showInfoWindow.columns || {};

        display = display === "" ? {} : display;


        for (i = 0; i < storeCount; i++) {
            data = store.getAt(i);

            toDisplay = {
                header: data.get(listAttributes.label),
                values: []
            };

            for (j in display) {

                tempItem = display[j];

                displaySource = tempItem.source !== "";
                displayValue = tempItem.value === 'true';
                displayTitle = tempItem.title === 'true';

                if (displaySource) {
                    if (displayValue && displayTitle) {
                        toDisplay.values.push(store.titles[tempItem.source] + ":" + data.get(tempItem.source));
                    } else if (displayTitle) {
                        toDisplay.values.push(store.titles[tempItem.source]);
                    } else if (displayValue) {
                        toDisplay.values.push(data.get(tempItem.source));
                    }
                }
            }

            templates.push(toDisplay);
        }

        if (listAttributes.itemWidthAutoMode === "maximum" && listAttributes.autoColumn === 'false' && widthItem === 'auto') {
            columns = parseInt(listAttributes.columnsCount);
            maxValue = Math.floor((containerLength - 15 - 4 * columns * (me.marginLeftRight + me.paddingLeftRight)) / columns);
        } else {
            maxValue = widthItem === 'auto' ? me.getMaxWidth(store, templates, headerFont, cellsFont) : widthItem;
        }

        for (i = 0; i < templates.length; i++) {

            data = templates[i];
            tempItem = me.generateItemContainer(maxValue, heightItem, data);

            items.push(tempItem);
        }


        return [maxValue, items];

    },

    generateItemContainer: function(width, height, data) {
        var me = this,
            CSSUtils = me.CSSUtils,

            dimStyle = CSSUtils.getAxiStyle(),
            noDimStyle = CSSUtils.getNoDimensionStyle(),
            finalReturn = {
                xtype: 'container',
                layout: {
                    type: 'table',
                    columns: 1,
                    tableAttrs: {
                        style: {
                            width: '100%',
                            height: '100%'
                        }
                    }
                },
                extraData: {
                    headerStyle: dimStyle,
                    valueStyle: noDimStyle,
                    header: data.header,
                    values: data.values,
                    width: '100%',
                },
                listeners: {
                    render: me.renderItemContainer
                },
                renderSubItemContainer: me.renderSubItemContainer,
                padding: me.buildPadding,
                style: 'text-overflow: ellipsis;overflow: hidden; margin-right: 2px;border-radius:5px;border: 1px #777 solid;' + CSSUtils.getRowColor("degradadoLista"),
            };

        if (width !== 'auto') {
            finalReturn.extraData.width = width;

            if (height === 'auto'){
                finalReturn.autoHeightEnabled = true;
            }else{
                finalReturn.autoHeightEnabled = false;
                 finalReturn.height = height;
            }

        }

        return finalReturn;

    },

    getMaxWidth: function(store, templates) {
        var me = this,
            i,
            j,
            max = 0,
            CSSUtils = me.CSSUtils,
            data,
            maxFunction = Math.max,
            measureHeader = Ext.getBody().createChild({
                tag: 'span',
                style: CSSUtils.getAxiStyle() + " white-space: nowrap;font-family: Verdana, Geneva,sans-serif;",
                cls: 'sencha-font-family'
            }),
            measureValue = Ext.getBody().createChild({
                tag: 'span',
                style: CSSUtils.getNoDimensionStyle() + " white-space: nowrap;font-family: Verdana, Geneva,sans-serif;",
                cls: 'sencha-font-family'
            });

        for (i = 0; i < templates.length; i++) {


            data = templates[i];
            max = maxFunction(max, Ext.util.TextMetrics.measure(measureHeader, data.header).width);

            for (j = 0; j < data.values.length; j++) {
                max = maxFunction(max, Ext.util.TextMetrics.measure(measureValue, data.values[j]).width);
            }


        }

        measureHeader.destroy();
        measureValue.destroy();

        return max+10;
    },

    renderItemContainer: function(me) {

        var extraData = me.extraData,
            width = extraData.width,
            i = 0,
            vals = extraData.values,
            lg = vals.length,
            margin =  me.autoHeightEnabled ? '0 0 5 0': '0 0 0 0',
            valuesLayout = {
                xtype: 'container',
                layout: {
                    type: 'table',
                    columns: 1,
                    tableAttrs: {
                        style: {
                            width: '100%',
                            height: '100%'
                        }
                    }
                },
                margin: margin,
                items: []
            },
            toAdd = [];
        // HEADER

        toAdd.push({
            xtype: 'box',
            html: extraData.header,
            style: extraData.headerStyle + 'text-overflow: ellipsis;white-space: nowrap; overflow: hidden;',
            cls: 'sencha-font-family grid-list-header-style',
            width: width,
            margin: margin,
            listeners: {
                render: me.renderSubItemContainer
            }
        });
        toAdd.push(valuesLayout);

        for (; i < lg; i++) {
            valuesLayout.items.push({
                xtype: 'box',
                width: width,
                html: vals[i],
                cls: "sencha-font-family",
                style: extraData.valueStyle + 'text-overflow: ellipsis;white-space: nowrap; overflow: hidden;',
                listeners: {
                    render: me.renderSubItemContainer
                }
            });
        }

        me.add(toAdd);


    },

    renderSubItemContainer: function(me) {

        Ext.create('Ext.tip.ToolTip', {
            target: me.el,
            cls: 'sencha-font-size tooltipCss',
            html: me.el.dom.innerHTML
        });

    }

});